const alunos = $('Buscar Alunos VIP Supabase').all().map(i => i.json);
const agora = new Date();
const diaSemana = agora.getDay(); // 0=Dom, 1=Seg, 2=Ter, 3=Qua, 4=Qui, 5=Sex, 6=Sab
const hora = agora.getHours();
const disparos = [];

// Função anti-mock
function ehMock(num) {
  if (!num) return true;
  const dig = num.replace(/\D/g, '');
  if (dig.length < 10) return true;
  if (['5532984587255', '553284587255', '553285066687'].includes(dig)) return false;
  const mocks = ['99998888', '99997777', '988881111', '123456', '000000'];
  return mocks.some(m => dig.includes(m));
}

for (const a of alunos) {
  if (!a.telefone || ehMock(a.telefone)) continue;
  const nome = a.nome || a.nome_aluno ? (a.nome || a.nome_aluno).split(' ')[0] : 'Guerreiro';
  const treino = a.treino_divisao || a.treino_atual || {};
  const treinoA = treino.treino_a || 'Peitoral & Ombros';
  const obj = (a.objetivo || '').toLowerCase();
  const restricoes = (a.restricoes_saude || '').toLowerCase();

  // 1. Verificação de Upsell de 30 dias
  let diasAtivos = 0;
  if (a.created_at || a.criado_em) {
    const inicio = new Date(a.created_at || a.criado_em);
    diasAtivos = Math.floor((agora - inicio) / (1000 * 60 * 60 * 24));
  }

  let elegivelUpsell = false;
  if (diasAtivos >= 28) {
    if (!a.ultimo_upsell_em && !a.ultimo_upsell_data) {
      elegivelUpsell = true;
    } else {
      const ultUpsell = new Date(a.ultimo_upsell_em || a.ultimo_upsell_data);
      const diasDesdeUlt = Math.floor((agora - ultUpsell) / (1000 * 60 * 60 * 24));
      if (diasDesdeUlt >= 28) elegivelUpsell = true;
    }
  }

  // Determinar se é teste manual ou rotina por cron
  const isTeste = $input.first().json.query && $input.first().json.query.teste;

  if (elegivelUpsell && hora >= 9 && hora <= 11) {
    let msgUpsell = '';
    if (restricoes.includes('dor') || restricoes.includes('joelho') || restricoes.includes('coluna')) {
      msgUpsell = `Fala, ${nome}! Fechando nosso ciclo de 30 dias de acompanhamento firme! 👊\n\nComo você me falou daquela sensibilidade nas articulações, muitos alunos meus zeram o incômodo usando o Colágeno Tipo II com Cúrcuma e Magnésio da nossa loja oficial: https://marcaopersonal.com#produtos\n\nSem pressão nenhuma, é recomendação técnica de treinador pra proteger sua estrutura! Bora pro treino!`;
    } else if (obj.includes('massa') || obj.includes('hipertrofia') || obj.includes('força')) {
      msgUpsell = `Fala, ${nome}! Completamos 30 dias de treino consistente, parabéns pela dedicação! 🔥\n\nPra essa fase de progressão de carga e ganho de volume muscular seco, a Creatina monohidratada 100% pura é o suplemento número 1 do mundo com comprovação total. Dá um confere lá no site oficial: https://marcaopersonal.com#produtos\n\nVai te dar aquela força na última repetição! Tamo junto!`;
    } else {
      msgUpsell = `Fala, ${nome}! 30 dias de foco e evolução na balança! Orgulho demais da sua disciplina! 🦁\n\nNormalmente a partir do primeiro mês o metabolismo dá uma desacelerada natural pra defender a gordura. Pra manter a queima acelerada e evitar aquele platô chato de estagnação, o ativador Azempika do nosso site ajuda demais a controlar apetite e acelerar a queima: https://marcaopersonal.com#produtos\n\nSe fizer sentido pra sua rotina, dá um confere lá!`;
    }

    disparos.push({
      telefone: a.telefone,
      remote_jid: a.remote_jid,
      tipo: 'upsell_30dias',
      eh_upsell: true,
      texto: msgUpsell
    });
  } else if (diaSemana === 1 || isTeste === 'segunda') {
    // Segunda-feira (07:30)
    disparos.push({
      telefone: a.telefone,
      remote_jid: a.remote_jid,
      tipo: 'checkin_segunda',
      eh_upsell: false,
      texto: `Fala, ${nome}! 🦁 Marcão na área! Segunda-feira é dia sagrado de recomeço com foco total!\n\nPrimeira missão do dia em jejum: sobe na sua Balança de Bioimpedância e me manda o print ou peso aqui! Sua meta hoje é água na garrafa (35ml por kg) e foco no Treino A (${treinoA})!\n\nBora começar a semana vencendo! Tamo junto!`
    });
  } else if (diaSemana === 3 || isTeste === 'quarta') {
    // Quarta-feira (18:00)
    disparos.push({
      telefone: a.telefone,
      remote_jid: a.remote_jid,
      tipo: 'checkin_quarta',
      eh_upsell: false,
      texto: `E aí, ${nome}! 👊 Quarta-feira, metade da semana vencida! Como tá a pegada dos treinos?\n\nPassando pra checar se o treino de hoje já tá pago! Me manda uma foto do seu prato de almoço ou jantar aqui pra eu dar uma olhada nos seus macros e calibrar sua dieta!\n\nMantém o ritmo firme, guerreiro!`
    });
  } else if (diaSemana === 5 || isTeste === 'sexta') {
    // Sexta-feira (18:30)
    disparos.push({
      telefone: a.telefone,
      remote_jid: a.remote_jid,
      tipo: 'checkin_sexta',
      eh_upsell: false,
      texto: `Fala, ${nome}! 🦁 Sextou com a sensação de dever cumprido!\n\nFechamos a meta semanal de treinos com chave de ouro! Agora no fim de semana, descanso com moderação e nada de jogar fora o esforço dos últimos 5 dias, combinado?\n\nSegura a hidratação e excelente descanso!`
    });
  }
}

return disparos.map(d => ({ json: d }));
